package com.xlf.utility.cache;

/**
 * 定义缓存生命周期管理的接口。
 * <p>
 * 此接口用于统一表示缓存数据的创建、获取以及删除操作的生命周期，
 * 从而为实现类提供一种通用的缓存管理方法。
 * <p>
 * 实现类可根据具体需求实现不同的缓存操作逻辑，例如内存缓存、
 * 文件缓存或分布式缓存等。
 * <p>
 * NOTICE: 实现此接口的类需确保线程安全以及数据一致性，具体细节
 * 根据使用场景自行设计。
 *
 * @author xiao_lfeng
 * @version v2.0.0-beta1
 * @since v2.0.0-beta1
 */
public interface CacheLifeCycle<T> {

    /**
     * 使用建造者模式创建并返回一个新的缓存对象。
     * <p>
     * 该方法的作用是根据预设的参数生成一个新的缓存实例，以支持缓存数据的生命周期管理。
     * 实现类可以根据具体需求生成不同类型的缓存对象，例如内存缓存对象或
     * 数据库缓存对象。此方法支持链式调用，允许灵活配置缓存对象的属性。
     * <p>
     * NOTICE: 此方法需要实现类确保线程安全，避免多线程环境下的竞争条件。
     * 此外，新创建的缓存对象应遵循实现类所定义的缓存策略。
     *
     * @return 返回一个新创建的缓存对象，具体类型由实现类决定。该对象包含了
     *         通过建造者模式设置的所有属性值。
     */
    T build();

    /**
     * 获取一个已存在的缓存对象。
     * <p>
     * 此方法用于从缓存中检索一个对象，具体的检索逻辑由实现类
     * 决定。通常适用于需要频繁访问缓存数据的场景。
     * <p>
     * 如果缓存中未找到对应的对象，返回值可能为 {@code null} 或
     * 实现类约定的默认值。
     * <p>
     * NOTICE: 实现类需要确保线程安全，避免在多线程环境下出现数据
     * 不一致的问题。同时，需根据具体需求设计缓存的过期策略。
     *
     * @return 返回已存在的缓存对象，如果对象不存在或已过期，
     *         则返回 {@code null} 或实现类定义的默认值。
     */
    T get(String id);

    /**
     * 删除指定的缓存对象。
     * <p>
     * 此方法用于从缓存中移除指定的对象。通过传入的参数，方法会匹配
     * 并删除对应的缓存内容。由于具体的删除逻辑依赖于实现类，因此实现
     * 类需明确定义删除操作的行为，例如是否支持深度清除、批量删除等。
     * <p>
     * 此操作可能涉及到缓存的刷写或同步，需要确保线程安全以及缓存数据的
     * 一致性。建议在多线程环境下进行适当加锁。
     * <p>
     * NOTICE: 请注意，调用此方法后，缓存中的数据将不可恢复。此外，如果删除
     * 的是共享的缓存数据，需特别注意可能带来的副作用。
     *
     * @param id 要删除的缓存对象的唯一标识符。
     * @return 如果删除成功，返回 {@code true}；否则，返回 {@code false}。
     *         当传入的对象为 {@code null} 或未找到时，可能返回 {@code false}。
     */
    boolean delete(String id);

    /**
     * 根据特定操作条件删除缓存数据。
     * <p>
     * 此方法的作用是根据实现类定义的操作条件，判断并删除满足条件的
     * 缓存数据。与 {@code delete(T entity)} 方法不同，{@code deleteIfOperate}
     * 的删除逻辑以内部条件或上下文为基础，而非外部传入的具体对象。
     * <p>
     * 具体实现逻辑完全依赖于实现类，例如：
     * <ul>
     * <li>清除不活跃的缓存数据。</li>
     * <li>移除过期的数据条目。</li>
     * <li>定期清除缓存以释放资源。</li>
     * </ul>
     * <p>
     * NOTICE: 实现类在执行删除操作时应确保线程安全，尤其是在多线程
     * 或共享缓存的情景下。此外，部分实现可能对性能有显著影响，例如
     * 全量遍历或复杂的匹配逻辑，因此建议对此方法的调用频率进行控制。
     */
    void deleteIfOperate();

    /**
     * 清除缓存对象的值。
     * <p>
     * 此方法用于清除当前缓存对象中的值，通常在需要重置或清空缓存时使用。
     * 实现类应确保此操作不会影响缓存的结构或其他元数据，仅清除存储的值。
     * <p>
     * NOTICE: 调用此方法后，缓存对象将不再包含任何有效数据，需谨慎使用。
     */
    void clearValue();
}
